function parseTrainingConfig(raw){
  if(!raw||raw.schema!=='training-limits-v1'||!raw.limits||!raw.versions)throw new Error('训练限额配置版本或字段无效');
  const integerFields=['timeout_seconds','window_periods','history_rows','tree_max_depth','tree_min_leaf','lstm_hidden_size','lstm_epochs'];
  const minimums={timeout_seconds:1,window_periods:1,history_rows:3,tree_max_depth:0,tree_min_leaf:1,lstm_hidden_size:1,lstm_epochs:1};
  for(const key of integerFields){const range=raw.limits[key];if(!Array.isArray(range)||range.length!==2||!range.every(Number.isSafeInteger)||range[0]<minimums[key]||range[0]>range[1])throw new Error('训练限额配置范围无效：'+key);}
  const learning=raw.limits.lstm_learning_rate;if(!Array.isArray(learning)||learning.length!==2||!learning.every(Number.isFinite)||learning[0]<=0||learning[0]>learning[1])throw new Error('训练限额配置范围无效：lstm_learning_rate');
  const versions=raw.versions;if(typeof versions.feature_schema!=='string'||!versions.feature_schema||!versions.algorithm||!versions.preprocessing)throw new Error('训练模型版本配置无效');
  for(const method of ['tree','lstm'])if(typeof versions.algorithm[method]!=='string'||!versions.algorithm[method]||typeof versions.preprocessing[method]!=='string'||!versions.preprocessing[method])throw new Error('训练模型版本配置无效：'+method);
  const backtest=raw.backtest,backtestIntegers=['max_targets','max_replicas','max_target_replica_pairs','min_history_periods','max_history_periods','max_tickets','max_sampling_attempts','max_model_validation_periods'];
  if(!backtest||backtestIntegers.some(key=>!Number.isSafeInteger(backtest[key])||backtest[key]<1)||backtest.min_history_periods>backtest.max_history_periods)throw new Error('回测限额配置无效');
  for(const key of ['timeout_seconds','budget_fen']){const range=backtest[key];if(!Array.isArray(range)||range.length!==2||!range.every(Number.isSafeInteger)||range[0]<1||range[0]>range[1])throw new Error('回测限额配置范围无效：'+key);}
  return {limits:raw.limits,versions,backtest};
}
