function markConnectionVerified(epoch,dataVerified){if(epoch!==connectionEpoch||!backend.ready||(['data','backtest','training','evidence'].includes(state.page)&&!dataVerified))return;document.body.dataset.serverStatus='verified';refreshStaticDrawRows();if(state.page==='data'&&el('source-quarantine-panel'))el('source-quarantine-panel').outerHTML=sourceQuarantinePanel();const notice=document.getElementById('connection-notice');if(notice){notice.hidden=true;notice.textContent='';}}
async function backendPost(path,body){
  if(!backend.ready||document.body.dataset.serverStatus==='unverified'){const error=new Error('本机服务尚未完成连接核验，请稍后重试；请求未发送。');error.notSent=true;throw error;}
  const epoch=connectionEpoch;let response;try{response=await fetch(path,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-DLT-CSRF':backend.csrf},body:JSON.stringify(body)});}catch(e){markConnectionUncertain('本机服务连接失败');throw e;}
  if(epoch!==connectionEpoch||!backend.ready||document.body.dataset.serverStatus==='unverified')throw new Error('连接状态在请求期间发生变化；结果待核实，请查询原请求状态，不要创建新请求。');
  if(response.status===401)markConnectionUncertain('本机会话已失效');
  let data;try{data=await response.json();}catch(e){if(epoch===connectionEpoch)markConnectionUncertain('本机服务响应无法完整核验，写入结果可能未知');throw new Error('本机服务响应无法完整核验；请查询原请求状态，不要创建新请求。');}
  if(epoch!==connectionEpoch||!backend.ready||document.body.dataset.serverStatus==='unverified')throw new Error('连接状态在响应核验期间发生变化；结果待核实，请查询原请求状态，不要创建新请求。');
  if(response.status>=500){markConnectionUncertain('本机服务发生内部错误，写入结果可能未知');throw new Error('本机服务发生内部错误；结果待核实，请查询原请求状态，不要创建新请求。');}
  if(!response.ok){const error=new Error(data.error||'请求失败');error.code=data.code;error.status=response.status;error.write=data.write;error.cancellation=data.cancellation;throw error;}return data;
}
function writeJournalStatus(entry,labels,fallback='待核对'){
  if(writeJournalNotSent(entry))return '尚未发送';
  if(entry?.status_unverified)return '本机记录待服务端核验';
  return labels?.[entry?.phase]||fallback;
}
function writeJournalNotSent(entry){return entry?.submission_state==='not_sent'&&!entry.status_unverified&&['submitted','prepared'].includes(entry.phase);}
function writeJournalNotSentHint(entry){return writeJournalNotSent(entry)?'<p class="section-subtext">连接核验前已拦截本次提交，确定未发送；连接恢复后可沿用原请求继续提交。</p>':'';}
function assertCurrentConnection(epoch){if(epoch!==connectionEpoch||!backend.ready||document.body.dataset.serverStatus==='unverified')throw new Error('连接世代已变化，服务端状态未核验');}
async function fetchCheckedConnection(url,options={},failureMessage='本机状态查询失败'){const epoch=connectionEpoch;assertCurrentConnection(epoch);let response;try{response=await fetch(url,options);}catch(error){markConnectionUncertain(failureMessage);throw error;}if(response.status===401)markConnectionUncertain('本机会话已失效');assertCurrentConnection(epoch);return {response,json:async()=>{const data=await response.json();assertCurrentConnection(epoch);return data;}};}
