async function refreshPaperWriteJournal(){const root=el('paper-write-journal'),page=state.page,epoch=connectionEpoch;if(!root)return;const current=()=>epoch===connectionEpoch&&page===state.page&&root===el('paper-write-journal')&&root.isConnected;try{const j=getPaperWriteJournal(),entries=await j.list(),checked=[];if(!current())return;for(const x of entries){try{checked.push(backend.ready?await j.check(x.request_key):x);}catch{checked.push(x);}if(!current())return;}if(!current())return;root.innerHTML=checked.length?`<div class="notice amber"><strong>复核、重算与更正重试待确认</strong>${checked.map(x=>{const followup=x.followup||x.response?.followup,subject=x.operation==='source_correction_retry'?`来源更正 ${x.request.scope==='issue'?'指定奖期':'全局'} · ${x.request.correction_id} · 后续 ${followup?.status||'待核验'}`:`${x.operation==='draw_resolve'?'开奖冲突复核':'纸面结果重算'} · 第 ${escape(x.request.issue)} 期`;return `<article class="section-space"><p>${subject} · ${escape(writeJournalNotSent(x)?'尚未发送':x.phase)} · ${escape(x.request_key)}</p>${writeJournalNotSent(x)?'<p class="section-subtext">连接核验前已拦截本次提交，确定未发送；连接恢复后可沿用原请求继续提交。</p>':''}<div class="actions"><button class="button" data-paper-write="check" data-request="${escape(x.request_key)}">查询</button>${x.phase==='submitted'?`<button class="button" data-paper-write="continue" data-request="${escape(x.request_key)}">继续原请求</button><button class="button" data-paper-write="fence" data-request="${escape(x.request_key)}">封止原请求</button>`:''}${x.phase==='fenced'?`<button class="button" data-paper-write="retry" data-request="${escape(x.request_key)}">关联同内容重试</button>`:''}${x.operation==='source_correction_retry'&&x.phase==='accepted'&&followup?.status==='failed'?`<button class="button" data-paper-write="retry" data-request="${escape(x.request_key)}">重新提交失败的复算</button>`:''}${x.phase==='accepted'?`<button class="button" data-paper-write="dismiss" data-request="${escape(x.request_key)}">核实后清理</button>`:''}</div>${followup?.status==='failed'?'<p class="section-subtext">复算已失败；重新提交会生成新请求键并保留本次请求记录。</p>':''}${x.server_result?`<pre class="draw-raw section-space">${escape(JSON.stringify(x.server_result.recalculations||x.server_result,null,2))}</pre>`:''}</article>`;}).join('')}</div>`:'';}catch(e){if(current())root.innerHTML=`<p class="section-subtext">待确认请求读取失败：${escape(e.message)}</p>`;}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-paper-write]');if(!b)return;b.disabled=true;try{const j=getPaperWriteJournal(),k=b.dataset.request,a=b.dataset.paperWrite,entry=(await j.list()).find(x=>x.request_key===k);if(a==='check')await j.check(k);else if(a==='continue')await j.continueOriginal(k);else if(a==='fence'){if(!confirm('封止后，迟到的写入请求将被拒绝。确认封止？'))return;await j.fence(k);}else if(a==='retry'){if(entry?.operation==='source_correction_retry'&&entry.phase==='accepted')await j.begin(entry.operation,entry.request);else await j.retry(k);}else if(a==='dismiss'){if(!confirm('确认服务端已接受此请求并核实其结果？仅清理本机副本。'))return;await j.dismiss(k);}await refreshPaperWriteJournal();await refreshBackend();}catch(x){toast('写入请求核对失败：'+x.message);await refreshPaperWriteJournal();}finally{if(b.isConnected)b.disabled=false;}});
function getSourceWriteJournal(){if(sourceWriteJournal)return sourceWriteJournal;if(!window.SourceWriteJournal||!window.indexedDB)throw new Error('本机来源写入暂存不可用，操作未发送');const api={
  async post(body){const path=body.old_review_id?'/api/source-corrections':'/api/source-reviews';return backendPost(path,body);},
  async status(key,digest){const {response,json}=await fetchCheckedConnection('/api/source-write-status?request_key='+encodeURIComponent(key)+'&request_sha256='+encodeURIComponent(digest),{credentials:'same-origin'},'来源写入状态查询失败');if(!response.ok)throw new Error('来源写入状态无法核验');return (await json()).write;},
  async fence(body){try{return (await backendPost('/api/source-writes/fence',body)).write;}catch(e){if(e.write)return e.write;throw e;}},
  async digest(request){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(window.SourceWriteJournal.canonical(request)));return Array.from(new Uint8Array(b),x=>x.toString(16).padStart(2,'0')).join('');},
  objectKey(operation,request){return operation==='source_review'?request.kind+':'+request.document_sha256:(request.issue?'issue:'+request.issue:'global')+':'+request.old_review_id;}
};sourceWriteJournal=window.SourceWriteJournal.coordinator({store:window.SourceWriteJournal.browserStore(window.indexedDB),locks:navigator.locks,api,uuid:()=>crypto.randomUUID()});return sourceWriteJournal;}
let recoveryWriteJournal=null,recoveryContinueKey=null,recoveryRetryKey=null;
function getRecoveryWriteJournal(){if(recoveryWriteJournal)return recoveryWriteJournal;const api={
  async digest(request){const h=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(window.SourceWriteJournal.canonical(request)));return Array.from(new Uint8Array(h),b=>b.toString(16).padStart(2,'0')).join('');},
  async post(x){const operation=x.source?'recovery_prepare':'recovery_activate',path=operation==='recovery_prepare'?'/api/encrypted-backup/prepare-candidate':'/api/encrypted-backup/activate-candidate',request=operation==='recovery_prepare'?{source:x.source,destination:x.destination,acknowledge:x.acknowledge}:{candidate:x.candidate,destination:x.destination,acknowledge:x.acknowledge,enable_restored_plans:x.enable_restored_plans};return backendPost(path,{...request,...(x.password?{password:x.password}:{}),request_key:x.request_key,request_sha256:x.request_sha256,...(x.retry_of?{retry_of:x.retry_of}:{})});},
  async status(key,digest,operation){const q=new URLSearchParams({request_key:key,operation,request_sha256:digest}),{response,json}=await fetchCheckedConnection('/api/recovery-write-status?'+q,{credentials:'same-origin'},'恢复写入状态查询失败');if(!response.ok)throw new Error('恢复写入状态无法核验');return (await json()).write;},
  async fence(x){try{return (await backendPost('/api/recovery-writes/fence',{request_key:x.request_key,operation:x.operation,request:x.request,request_sha256:x.request_sha256,...(x.retry_of?{retry_of:x.retry_of}:{})})).write;}catch(error){if(error.write?.status==='fenced')return error.write;throw error;}},
  async objectKey(operation,request){const p=String(request.destination).replace(/\\/g,'/').toLowerCase(),h=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(p));return operation+':'+Array.from(new Uint8Array(h),b=>b.toString(16).padStart(2,'0')).join('');}
};recoveryWriteJournal=window.SourceWriteJournal.coordinator({store:window.SourceWriteJournal.browserStore(window.indexedDB),locks:navigator.locks,api,uuid:()=>crypto.randomUUID()});return recoveryWriteJournal;}
async function refreshRecoveryWriteJournal(){const root=el('restore-write-journal'),page=state.page,epoch=connectionEpoch;if(!root)return;const current=()=>epoch===connectionEpoch&&page===state.page&&root===el('restore-write-journal')&&root.isConnected;try{const j=getRecoveryWriteJournal(),entries=(await j.list()).filter(x=>x.operation.startsWith('recovery_')),checked=[];if(!current())return;for(const x of entries){try{checked.push(backend.ready?await j.check(x.request_key):x);}catch{checked.push(x);}if(!current())return;}if(!current())return;root.innerHTML=checked.length?`<div class="notice amber"><strong>恢复文件写入待确认</strong>${checked.map(x=>`<article class="section-space"><p>${x.operation==='recovery_prepare'?'准备候选':'激活候选'} · ${escape(writeJournalNotSent(x)?'尚未发送':x.phase)} · ${escape(x.request_key)}</p>${writeJournalNotSent(x)?'<p class="section-subtext">连接核验前已拦截本次提交，确定未发送；连接恢复后可沿用原请求继续提交。</p>':''}<div class="actions"><button class="button" data-recovery-write="check" data-request="${escape(x.request_key)}">查询</button>${x.phase==='submitted'?`<button class="button" data-recovery-write="continue" data-request="${escape(x.request_key)}">继续原请求</button><button class="button" data-recovery-write="fence" data-request="${escape(x.request_key)}">封止原请求</button>`:''}${x.phase==='fenced'?`<button class="button" data-recovery-write="retry" data-request="${escape(x.request_key)}">换新目标关联重试</button>`:''}${x.phase==='accepted'?`<button class="button" data-recovery-write="dismiss" data-request="${escape(x.request_key)}">核实后清理</button>`:''}</div>${x.server_result?.staging_cleanup==='failed'?'<p class="error-text">临时文件清理失败；请检查候选所在目录。</p>':''}</article>`).join('')}</div>`:'';}catch(e){if(current())root.innerHTML=`<p class="section-subtext">恢复待确认记录读取失败：${escape(e.message)}</p>`;}}
