const el=id=>document.getElementById(id);
const escape=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=v=>(v*100).toFixed(2)+'%';
function decimalYuan(value){
  if(!['string','number'].includes(typeof value)||(typeof value==='number'&&(!Number.isFinite(value)||Math.abs(value)>Number.MAX_SAFE_INTEGER)))return '金额待复核';
  const raw=String(value);if(raw.length>512)return '金额待复核';
  const match=/^([+-]?)(?:(\d+)(?:\.(\d*))?|\.(\d+))(?:[eE]([+-]?\d{1,4}))?$/.exec(raw);
  if(!match)return '金额待复核';
  const whole=match[2]||'0',fraction=match[3]??match[4]??'',exponent=Number(match[5]||0);
  if(Math.abs(exponent)>256)return '金额待复核';
  try{const digits=BigInt(whole+fraction),shift=exponent-fraction.length+2;if(Math.abs(shift)>768)return '金额待复核';
    const cents=shift>=0?digits*10n**BigInt(shift):(digits*2n+10n**BigInt(-shift))/(2n*10n**BigInt(-shift));
    return (match[1]==='-'&&cents!==0n?'−':'')+(cents/100n).toString()+'.'+String(cents%100n).padStart(2,'0')+' 元';
  }catch{return '金额待复核';}
}
function exactMeanYuan(mean){
  const pair=mean?.fraction;if(!Array.isArray(pair)||pair.length!==2)return '金额待复核';
  const valid=x=>(typeof x==='string'&&/^-?\d{1,512}$/.test(x))||(typeof x==='number'&&Number.isSafeInteger(x));
  if(!pair.every(valid))return '金额待复核';
  try{let n=BigInt(pair[0]),d=BigInt(pair[1]);if(n<0n||d<=0n)return '金额待复核';const cents=(n*200n+d)/(2n*d);return (cents/100n).toString()+'.'+String(cents%100n).padStart(2,'0')+' 元';}catch{return '金额待复核';}
}
