function navigate(page,{force=false}={}){if(!pages.some(p=>p[0]===page))page='overview';if(page!==state.page&&!force&&hasUnsubmittedPageEdits()){if(!window.confirm('当前页面有尚未保存的编辑内容，离开后可能丢失。仍要离开吗？'))return false;discardUnsubmittedPageEdits();}if(['data','backtest','training','evidence'].includes(page)&&state.page!==page&&backend.ready){markConnectionChecking();queueMicrotask(()=>refreshBackend());}if(page!==state.page&&(page==='overview'||state.page==='overview')){overviewState.generation++;overviewState.data=null;overviewState.error='';overviewState.loading=false;overviewState.rendered='';}if(page==='comparison'&&state.page!=='comparison'){crossPortfolio.epoch++;crossPortfolio.options=[];crossPortfolio.selected=[];crossPortfolio.loaded=false;crossPortfolio.loading=false;crossPortfolio.ready=false;crossPortfolio.busy=false;crossPortfolio.error='';crossPortfolio.result=null;}state.page=page;location.hash=page;el('breadcrumb').textContent=pages.find(p=>p[0]===page)[1];el('navigation').innerHTML='<div class="nav-group-label">研究空间</div>'+pages.map(([id,title,ico])=>`<a class="nav-item ${id===page?'active':''}" href="#${id}" ${id===page?'aria-current="page"':''}>${icon(ico)}<span>${title}</span></a>`).join('');el('main').innerHTML=renderers[page]();el('sidebar').classList.remove('mobile-open');if(el('drawer').hidden)el('scrim').hidden=true;el('menu-button').setAttribute('aria-expanded','false');window.scrollTo(0,0);if(['prospective','evidence'].includes(page))queueMicrotask(()=>refreshProspectiveClosureWriteJournal());if(page==='prospective')queueMicrotask(()=>backend.ready?refreshBackend():refreshFixedExperimentWrites());if(['training','backtest'].includes(page))queueMicrotask(refreshTaskWriteJournal);if(page==='training')queueMicrotask(()=>refreshTrainingSearchJournal({resume:true}));return true;}

function overviewDate(value){if(!value)return '暂无';const date=new Date(value);return Number.isNaN(date.getTime())?'时间无法解析':date.toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});}
function overviewContent(data){
  if(!data){const message=overviewState.error||'正在读取本机研究记录…';return `<section class="panel"><div class="panel-body"><div class="notice ${overviewState.error?'amber':''}" role="status">${escape(message)}</div><p class="section-subtext">既有封存记录仍可从页面右上方查看。</p></div></section>`;}
  const {snapshots,jobs,plans,worker,experiments,series,detail}=data,snapshot=snapshots[0]||null;
  const ready=new Set(jobs.filter(j=>j.status==='complete'&&j.artifact_status==='ready'&&j.artifact_id).map(j=>j.artifact_id));
  const issues=new Set(experiments.filter(e=>e.paper_status==='locally_attested'&&e.status!=='review_required').map(e=>e.target_issue));
  const needReview=experiments.filter(e=>e.status==='review_required'||['blocked','review_required'].includes(e.paper_status));
  const pending=experiments.filter(e=>e.paper_status!=='locally_attested').sort((a,b)=>(a.target_date||'9999').localeCompare(b.target_date||'9999')||String(a.target_issue).localeCompare(String(b.target_issue))||String(a.request_key).localeCompare(String(b.request_key)));
  const labels={waiting:'等待开奖或数据',blocked:'计算阻断',review_required:'待复核',locally_attested:'本人留存已计算',closed:'已关闭'};
  const runs=plans.flatMap(p=>Array.isArray(p.runs)?p.runs:[]).filter(r=>r.ended_at).sort((a,b)=>String(b.ended_at).localeCompare(String(a.ended_at)));
  const last=runs[0],success=runs.find(r=>r.status==='success'),runLabels={success:'成功',failed:'失败',interrupted:'中断',cancelled:'取消'};
  const workerLabels={running:'更新线程运行中',not_started:'更新线程尚未启动',occupied:'由其他进程持有更新锁',stopped:'更新线程已停止',failed:'更新线程异常'};
  const tasks=jobs.filter(j=>['running','failed','cancelled'].includes(j.status)||j.artifact_status==='review_required').slice(0,5);
  const unregistered=series.filter(s=>!s.closure).reduce((total,s)=>{const m=s.content?.manifest,done=new Set((s.periods||[]).map(p=>p.issue));return total+(m?.observation_issues||[]).filter(i=>!done.has(i)).length;},0);
  const latest=detail?.draws?.[0],source=detail?.observation;
  return `<div class="two-column"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>本机研究进展</h2><p>下列数字来自本机最近读取的记录，各项读取时间可能略有差异。</p></div>${tag('本机记录','blue')}</div><div class="panel-body"><div class="facts-row">${fact('最近创建快照',snapshot?'第 '+escape(snapshot.last_issue)+' 期':'暂无')}${fact('快照包含',snapshot?escape(snapshot.row_count)+' 期':'暂无')}${fact('可用模型产物',String(ready.size))}${fact('本人留存已计算奖期',String(issues.size))}</div><p class="section-subtext">${snapshot?`快照 ${escape(snapshot.id.slice(0,12))} · 覆盖 ${escape(snapshot.first_issue)}—${escape(snapshot.last_issue)} 期；按快照创建顺序选择，不代表官方最新期。`:'尚未载入本机数据快照。'}${source?` 来源：${escape(source.source)}；观察时间 ${escape(overviewDate(source.observed_at))}。`:''}${latest?.conflict?' 最新期存在来源冲突，请核对。':''}</p><p class="section-subtext">同一期多个实验或副本只计一个已计算奖期；本人留存的来源和时间未经独立认证，不能据此认定方法有效。</p><div class="actions">${go('数据与规则','data')}${go('模型训练','training')}${go('查看证据','evidence')}</div></div></section><section class="panel"><div class="panel-head"><div><h2>已登记奖期</h2><p>按本人核对的开奖日期排列；不明日期列在后面。</p></div>${tag('待处理 '+pending.length,'blue')}</div><div class="panel-body">${pending.length?pending.slice(0,5).map(e=>`<div class="review-row"><div><strong>第 ${escape(e.target_issue)} 期 · ${escape(e.hypothesis)}</strong><p class="section-subtext">${e.target_date?escape(e.target_date)+' / ':''}${escape(labels[e.paper_status]||e.paper_status)}${e.status==='review_required'?' / 登记待复核':''} · ${escape(e.replicas)} 个副本</p></div>${go('查看实验','prospective')}</div>`).join(''):'<p class="section-subtext">暂无等待处理的本机登记记录。</p>'}${pending.length>5?'<p class="section-subtext">这里只显示前 5 条，完整记录见前瞻实验。</p>':''}<p class="section-subtext">未关闭实验版本的固定观察范围中尚未登记 ${unregistered} 期；未登记不表示仍未截止。</p>${go('查看实验版本','prospective')}</div></section><section class="panel"><div class="panel-head"><h2>训练任务</h2>${tag('最近 '+Math.min(jobs.length,5)+' 条')}</div><div class="panel-body">${jobs.length?jobs.slice(0,5).map(j=>`<div class="review-row"><span>${escape(j.name||'训练任务')}<small class="muted" style="display:block">${escape(overviewDate(j.created_at))} · ${escape(({running:'运行中',complete:'已完成',failed:'失败',cancelled:'已取消'})[j.status]||j.status)}${j.artifact_status==='review_required'?' / 产物待复核':''}</small></span>${go('查看任务','training')}</div>`).join(''):'<p class="section-subtext">尚无本机训练任务；完成训练后还需独立评估。</p>'}${tasks.length?'<p class="section-subtext">存在进行中、失败、取消或产物待复核的任务，请查看任务记录。</p>':''}</div></section></div><aside class="stack"><section class="panel"><div class="panel-head"><h2>更新状态</h2></div><div class="panel-body"><p>${escape(workerLabels[worker?.state]||'后台状态未知')}</p><p class="section-subtext">${escape(plans.filter(p=>p.enabled).length)} / ${escape(plans.length)} 个计划已启用${worker?.error?'；'+escape(worker.error):''}</p><p class="section-subtext">最近结束：${last?escape(runLabels[last.status]||last.status)+' / '+escape(overviewDate(last.ended_at)):'暂无'}<br>最近成功：${success?escape(overviewDate(success.ended_at)):'暂无'}</p>${go('查看更新记录','data')}</div></section><section class="panel"><div class="panel-head"><h2>需要核对</h2></div><div class="panel-body"><p>${needReview.length?'有 '+needReview.length+' 条实验被阻断或待复核。':'没有发现被阻断或待复核的本机实验记录。'}</p><p class="section-subtext">这只反映当前检查范围，不代表官方资料已认证或所有历史结果有效。</p>${go('查看前瞻实验','prospective')}</div></section><section class="notice amber">训练完成或出现中奖结果，都不自动证明方法优于随机或可以盈利。</section></aside></div>`;
}
function paintOverview(){const root=el('live-overview');if(!root)return;const html=overviewContent(overviewState.data);if(html!==overviewState.rendered){root.innerHTML=html;overviewState.rendered=html;}}
function invalidateOverview(message){overviewState.generation++;overviewState.loading=false;overviewState.data=null;overviewState.error=message;paintOverview();}
async function refreshOverview(snapshots,jobs){if(overviewState.loading||state.page!=='overview')return;const generation=overviewState.generation,connection=connectionEpoch,current=()=>generation===overviewState.generation&&connection===connectionEpoch&&backend.ready&&state.page==='overview';overviewState.loading=true;try{const responses=await Promise.all(['/api/update-plans','/api/experiments','/api/experiment-series'].map(url=>fetch(url,{credentials:'same-origin'})));if(!current())return;if(responses.some(r=>!r.ok))throw new Error('研究记录读取失败');const [update,exp,versions]=await Promise.all(responses.map(r=>r.json()));if(!current())return;let detail=null;if(snapshots.length){const response=await fetch('/api/draws?snapshot='+encodeURIComponent(snapshots[0].id),{credentials:'same-origin'});if(!current())return;if(!response.ok)throw new Error('快照来源读取失败');detail=await response.json();if(!current())return;if(detail.snapshot_id!==snapshots[0].id)throw new Error('快照来源不匹配');}if(!current())return;overviewState.data={snapshots,jobs,plans:update.plans,worker:{state:update.worker?.state,error:update.worker?.error},experiments:exp.experiments,series:versions.series,detail};overviewState.error='';paintOverview();}catch(e){if(current()){overviewState.data=null;overviewState.error='本机研究记录暂时无法核验，请稍后重试。';paintOverview();}}finally{if(generation===overviewState.generation)overviewState.loading=false;}}
function overview(){overviewState.rendered='';return heading('研究概览','查看本机数据、研究任务和证据进展。',button('查看封存记录','sealed','','file')+'<button type="button" class="button primary" data-go="prospective">前瞻实验</button>')+`<div id="overview-connection-notice" class="notice amber section-space" role="status" aria-live="polite">本机研究状态未重新核验，旧数据已隐藏；连接恢复后会重新读取。</div><div id="live-overview" aria-live="polite">${overviewContent(overviewState.data)}</div>`;}

function calcKey(){return [state.budget,state.front,state.back,state.additional,state.samples,D.payoutScenario.issue].join('|');}
function calcInput(){return {budget:state.budget,front:state.front,back:state.back,additional:state.additional,samples:state.samples,seed:20261029,scenario:D.payoutScenario};}
function invalidateCalc(){if(state.calcWorker){state.calcWorker.terminate();state.calcWorker=null;}state.calcBusy=false;state.calcProgress=0;state.calcError='';}
function spendingLabel(cost){return cost===state.budget?tag('同预算','blue'):cost>state.budget?tag('超出预算','amber'):tag('预算内，余 '+(state.budget-cost)+' 元',cost===0?'':'amber');}
function calculationResults(){
  if(state.calcBusy)return `<div class="panel-body" role="status" aria-live="polite"><h3>正在按当前参数计算</h3><div class="progress-track"><div style="transform:scaleX(${state.calcProgress/100})"></div></div><p class="section-subtext">${escape(state.calcMessage)}。可停止计算，或修改参数后重新开始。</p></div>`;
  if(state.calcError)return `<div class="panel-body"><div class="notice red" role="alert">${escape(state.calcError)}</div></div>`;
  const r=state.calcResult;
  if(!r||state.calcResultKey!==calcKey())return `<div class="calculation-empty" role="status"><span class="calculation-state-dot" aria-hidden="true"></span><div><h3>${r?'参数已变更，需要重新计算':'等待计算'}</h3><p>使用当前预算与复式结构计算中奖概率和收益分布。</p></div></div>`;
  const probability=p=>(p*100).toFixed(2)+'%';
  const interval=range=>range?`${probability(range[0])}—${probability(range[1])}`:'';
  const metric=(value,range,type)=>`<div class="probability-cell"><span class="probability-value num">${probability(value)}</span><div class="probability-track" aria-hidden="true"><span class="probability-fill ${type}" style="width:${Math.max(0,Math.min(100,value*100))}%"></span></div>${range?`<small>95%区间 ${interval(range)}</small>`:'<small>精确概率</small>'}</div>`;
  return `<div class="result-table-intro"><div class="calculation-summary"><span>${tag('已按当前参数重算','green')} <span class="small muted">${state.calcCompletedAt}（北京时间）</span></span><span class="small muted">种子 ${r.parameters.seed} / 模拟 ${(r.parameters.samples/10000).toLocaleString()} 万次</span></div><p class="section-subtext">条形统一使用 0—100% 刻度；整期盈利指税后总奖金超过该方案实际成本。投入不同的方案不作收益排名。</p><p class="table-scroll-hint">左右滑动查看全部指标</p></div><div class="table-wrap probability-table-scroll" tabindex="0" role="region" aria-label="方案概率与收益明细，可横向滚动"><table class="data-table calculation-table probability-table"><colgroup><col class="plan-column"><col class="probability-column"><col class="probability-column"><col><col></colgroup><thead><tr><th scope="col">方案 / 方法</th><th scope="col" class="align-right"><span class="metric-label"><i class="metric-dot"></i>中任意奖</span></th><th scope="col" class="align-right"><span class="metric-label"><i class="metric-dot profit"></i>整期盈利</span></th><th scope="col" class="align-right"><span class="prize-expectation-label" title="包含未中奖及罕见大奖" tabindex="0" aria-description="包含未中奖及罕见大奖">理论平均奖金（税前）</span></th><th scope="col" class="align-right">一等奖概率</th></tr></thead><tbody>${r.rows.map(x=>`<tr><th scope="row" class="plan-name">${escape(x.name)}<small>${x.method==='exact'?'精确计算':'随机模拟'} / 实际成本 ${x.cost} 元</small></th><td class="align-right">${metric(x.pAny,x.anyInterval,'')}</td><td class="align-right">${metric(x.pProfit,x.profitInterval,'profit')}</td><td class="align-right">${x.grossExpected.toFixed(2)} 元<small>按组合概率计算</small></td><td class="align-right">${x.pFirst?(x.pFirst*100).toPrecision(4)+'%':'0%'}</td></tr>`).join('')}</tbody></table></div><div class="table-note">分散单式为固定种子生成的一组号码，不代表所有号码布局。精确计算覆盖全部 ${r.totalOutcomes.toLocaleString()} 种开奖结果。模拟的95%区间仅反映抽样误差；理论平均奖金（税前）由组合概率计算，不用有限模拟均值估计极罕见大奖。${escape(r.assumption)}</div>`;
}
function startCalculation(){
  invalidateCalc();state.calcBusy=true;state.calcProgress=0;state.calcMessage='准备计算';state.calcError='';const key=calcKey(),input=calcInput();
  if(state.page==='comparison')el('main').innerHTML=comparison();
  try{
    const workerCode=`const compute=${window.computeDltComparison.toString()};self.onmessage=e=>{try{const result=compute(e.data,p=>self.postMessage({progress:p}));self.postMessage({result});}catch(error){self.postMessage({error:error.message});}};`;
    const url=URL.createObjectURL(new Blob([workerCode],{type:'text/javascript'}));const worker=new Worker(url);URL.revokeObjectURL(url);state.calcWorker=worker;
    worker.onmessage=event=>{if(state.calcWorker!==worker||key!==calcKey())return;const data=event.data;if(data.progress){state.calcProgress=data.progress.percent;state.calcMessage=data.progress.message;if(state.page==='comparison'){const panel=el('comparison-results');if(panel)panel.innerHTML=calculationResults();}return;}state.calcBusy=false;state.calcWorker=null;worker.terminate();if(data.error){state.calcError='计算未完成：'+data.error;}else{state.calcResult=data.result;state.calcResultKey=key;state.comparisonSaved={budget:state.budget,front:state.front,back:state.back,additional:state.additional,samples:state.samples};state.comparisonDirty=false;state.calcCompletedAt=new Date().toLocaleTimeString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'});toast('当前预算和复式参数已重新计算。');}if(state.page==='comparison')el('main').innerHTML=comparison();};
    worker.onerror=()=>{if(state.calcWorker!==worker)return;worker.terminate();state.calcWorker=null;state.calcBusy=false;state.calcError='计算任务未能启动，请使用本机预览入口或刷新后重试。';if(state.page==='comparison')el('main').innerHTML=comparison();};worker.postMessage(input);
  }catch(error){state.calcBusy=false;state.calcError='计算任务未能启动：'+error.message;if(state.page==='comparison')el('main').innerHTML=comparison();}
}
function actualPortfolioComparison(){const c=crossPortfolio;if(backend.ready&&!c.loaded&&!c.loading)queueMicrotask(loadCrossOptions);const options=c.options.map(item=>{const checked=c.selected.includes(item.request_key),eligible=item.status==='research_draft'&&!!item.source_issue;const label=eligible?`${generationMethods[item.method]||item.method} / ${structureNames[item.structure]||item.structure} / 目标第 ${item.target_issue} 期 / 草稿 ${item.pair_key.slice(0,8)}`:'记录待复核';return `<div class="review-row"><label><input type="checkbox" data-cross-evaluation="${escape(item.request_key)}" ${checked?'checked':''} ${eligible||checked?'':'disabled'}> ${escape(label)}<small class="muted" style="display:block">${eligible?`${item.scenario_kind==='custom_payout_v1'?'自定义：'+escape(item.scenario_label)+'（研究假设）':`历史第 ${escape(item.source_issue)} 期 / 快照 ${escape(item.snapshot_id.slice(0,8))}`} / 评估 ${escape(item.request_key.slice(0,8))} / 预算 ${(Number(item.budget_fen)/100).toFixed(2)} 元 / 投入 ${(Number(item.cost_fen)/100).toFixed(2)} 元 / ${escape(item.samples)} 次 / 种子 ${escape(item.seed)}`:escape(item.reason||'记录不可用于比较')}</small></label></div>`;}).join('');return `<section id="cross-portfolio-panel" class="panel section-space"><div class="panel-head"><div><h2>已保存组合对照</h2><p>比较 2—3 份已评估组合，使用相同目标期与奖金情景。</p></div>${tag('实际子注','blue')}</div><div class="panel-body">${!backend.ready?'<p class="section-subtext">连接本机服务后可查看已保存评估。</p>':c.loading?'<p class="section-subtext">正在读取评估记录。</p>':!c.loaded?'<p class="section-subtext">准备读取已保存评估。</p>':options?`<details><summary class="text-button">选择已保存评估（最近 ${c.options.length} 条）</summary><p class="section-subtext">每份组合只能选一条；若尚未评估，请先在方案生成页计算收益分布。</p>${options}<div class="inline-form-actions"><button type="button" class="button" data-action="cross-compare" ${c.busy?'disabled':''}>${c.busy?'正在核验…':'核验并比较'}</button><button type="button" class="button" data-action="cross-clear">清空选择</button></div></details>`:'<p class="section-subtext">暂无已保存评估；请先在方案生成页生成并评估组合。</p>'}<div class="actions section-space">${c.selected.length&&!options?'<button type="button" class="text-button" data-action="cross-clear">清空选择</button>':''}<button type="button" class="text-button" data-action="cross-reload" ${c.loading||!backend.ready?'disabled':''}>刷新评估列表</button><button type="button" class="text-button" data-go="generation">前往方案生成</button></div><div id="cross-portfolio-result" aria-live="polite">${crossPortfolioResult()}</div></div></section>`;}
function crossPortfolioResult(){const c=crossPortfolio;if(c.error)return `<div class="notice amber section-space">${escape(c.error)}</div>`;if(!c.ready||!c.result)return c.selected.length?'<p class="section-subtext section-space">选择完成后，请核验并比较；更改选择会隐藏旧结果。</p>':'';const entries=c.result.entries;if(!Array.isArray(entries)||entries.length!==c.selected.length||entries.some((entry,index)=>entry.request_key!==c.selected[index]))return '<div class="notice amber section-space">记录不完整或与选择不一致，当前结果已隐藏。</div>';const amounts=entries.map(e=>e.pair.candidate.cost_fen),different=new Set(amounts).size>1,money=decimalYuan,prob=p=>pct(p.estimate)+'<small>95% 模拟区间 '+pct(p.interval_95[0])+'—'+pct(p.interval_95[1])+'</small>',scenario=entries[0].request.scenario;return `<div class="section-space"><div class="notice ${different?'amber':''}">${different?'各组合实际投入不同，列出成本与余额，不进行收益排名。':'各组合实际投入相同；结果不构成收益排名或购买建议。'}</div><p class="section-subtext">${scenario.kind==='custom_payout_v1'?'自定义：'+escape(scenario.custom_input.label)+'（研究假设）':`第 ${escape(scenario.source_issue)} 期历史奖金 / 快照 ${escape(scenario.source_dependency.snapshot_id.slice(0,12))}`}；固定单注奖金，不重算新增中奖者分奖或限额；各方案假设无其他同期开奖中奖收入。税费与规则为研究假设，不是下一期预测。各评估分别运行并显示种子，区间只表示模拟抽样误差，不用于显著性判断。金额按分四舍五入显示，原始结果保留精度。</p><div class="table-wrap probability-table-scroll" tabindex="0" role="region" aria-label="已保存组合比较"><table class="data-table"><thead><tr><th>组合 / 方法</th><th class="align-right">预算 / 投入 / 余额</th><th class="align-right">中任意奖</th><th class="align-right">回本</th><th class="align-right">整期盈利</th><th class="align-right">一等奖号码覆盖</th><th class="align-right"><span title="包含未中奖及罕见大奖" tabindex="0">理论平均奖金（税前）</span></th><th class="align-right">净收益 5% / 50% / 95% 分位</th></tr></thead><tbody>${entries.flatMap(entry=>[['candidate','候选方案'],['control','随机对照']].map(([key,label])=>{const pair=entry.pair,portfolio=pair[key],p=entry.result.portfolios[key],cfg=pair.config;return `<tr><td>${escape(generationMethods[cfg.method]||cfg.method)} / ${escape(structureNames[cfg.structure]||cfg.structure)} / ${label}<small>草稿 ${escape(entry.pair_key.slice(0,8))} · ${escape(portfolio.count)} 注 · 目标 ${escape(cfg.target_issue)} · ${escape(entry.request.samples)} 次 / 种子 ${escape(entry.request.seed)}<br>基本 ${(Number(cfg.base_price_fen)/100).toFixed(2)} 元 / 追加 ${(Number(cfg.additional_price_fen)/100).toFixed(2)} 元</small></td><td class="align-right">${money(Number(cfg.budget_fen)/100)} / ${money(Number(portfolio.cost_fen)/100)} / ${money(Number(portfolio.remaining_fen)/100)}</td><td class="align-right">${prob(p.any_prize)}</td><td class="align-right">${prob(p.break_even)}</td><td class="align-right">${prob(p.profit)}</td><td class="align-right">${(p.jackpot_coverage.probability*100).toPrecision(4)}%<small>完整号码覆盖精确值</small></td><td class="align-right">${exactMeanYuan(p.mean_gross_tax_before)}</td><td class="align-right">${money(p.net_quantiles_yuan.p05)} / ${money(p.net_quantiles_yuan.p50)} / ${money(p.net_quantiles_yuan.p95)}</td></tr>`;})).join('')}<tr><td>不参与购买</td><td class="align-right">— / 0.00 元 / —</td><td class="align-right">—</td><td class="align-right">—</td><td class="align-right">—</td><td class="align-right">—</td><td class="align-right">0.00 元</td><td class="align-right">0.00 元</td></tr></tbody></table></div></div>`;}
function updateCrossResult(){const root=el('cross-portfolio-result');if(root)root.innerHTML=crossPortfolioResult();}
function redrawCrossPanel(){const root=el('cross-portfolio-panel');if(!root)return;const open=!!root.querySelector('details')?.open;root.outerHTML=actualPortfolioComparison();const replacement=el('cross-portfolio-panel');if(open&&replacement?.querySelector('details'))replacement.querySelector('details').open=true;}
async function loadCrossOptions(){const c=crossPortfolio;if(!backend.ready||c.loading)return;const epoch=++c.epoch,connection=connectionEpoch,current=()=>c.epoch===epoch&&connection===connectionEpoch&&backend.ready&&document.body.dataset.serverStatus!=='unverified'&&state.page==='comparison';c.loading=true;c.busy=false;c.ready=false;c.error='';redrawCrossPanel();try{const {response,json}=await fetchCheckedConnection('/api/evaluations/comparison-options',{credentials:'same-origin'},'评估列表连接失败');if(!current())return;if(!response.ok)throw new Error('评估列表读取失败');const data=await json();if(!current())return;c.options=Array.isArray(data.options)?data.options:[];c.loaded=true;}catch(e){if(current()){c.loaded=true;c.error='无法读取评估列表：'+e.message;}}finally{if(c.epoch===epoch){c.loading=false;if(state.page==='comparison')redrawCrossPanel();}}}
async function runCrossComparison(background=false){const c=crossPortfolio,keys=[...c.selected];if(c.busy)return;if(keys.length<2||keys.length>3){c.ready=false;c.error='请选择 2—3 份不同组合的评估。';updateCrossResult();return;}const epoch=++c.epoch,connection=connectionEpoch,current=()=>c.epoch===epoch&&connection===connectionEpoch&&backend.ready&&document.body.dataset.serverStatus!=='unverified'&&state.page==='comparison'&&JSON.stringify(c.selected)===JSON.stringify(keys);c.busy=true;if(!background){c.ready=false;c.error='';updateCrossResult();}try{const query=new URLSearchParams();keys.forEach(key=>query.append('key',key));const {response,json}=await fetchCheckedConnection('/api/evaluations/compare?'+query.toString(),{credentials:'same-origin'},'评估比较连接失败');if(!current())return;if(!response.ok){const failure=await json();throw new Error(failure.error||'比较核验失败');}const data=await json();if(!current())return;const changed=JSON.stringify(c.result)!==JSON.stringify(data)||!c.ready;c.result=data;c.ready=true;c.error='';if(changed)updateCrossResult();}catch(e){if(current()){c.ready=false;c.error='无法显示比较：'+e.message;updateCrossResult();}}finally{if(c.epoch===epoch){c.busy=false;if(current())redrawCrossPanel();}}}
document.addEventListener('change',event=>{const input=event.target.closest('[data-cross-evaluation]');if(!input)return;const c=crossPortfolio,key=input.dataset.crossEvaluation,item=c.options.find(x=>x.request_key===key);if(input.checked&&!c.selected.includes(key)){if(c.selected.length>=3){input.checked=false;toast('最多选择 3 份组合。');return;}if(c.selected.some(id=>c.options.find(x=>x.request_key===id)?.pair_key===item?.pair_key)){input.checked=false;toast('同一组合请选择一条评估。');return;}c.selected.push(key);}else if(!input.checked){c.selected=c.selected.filter(x=>x!==key);if(!item||item.status!=='research_draft')input.disabled=true;}c.epoch++;c.busy=false;c.ready=false;c.error='';updateCrossResult();});
document.addEventListener('click',event=>{const button=event.target.closest('[data-action="cross-compare"],[data-action="cross-clear"],[data-action="cross-reload"]');if(!button||button.disabled)return;if(button.dataset.action==='cross-compare')runCrossComparison();else if(button.dataset.action==='cross-reload')loadCrossOptions();else{crossPortfolio.epoch++;crossPortfolio.selected=[];crossPortfolio.ready=false;crossPortfolio.busy=false;crossPortfolio.error='';crossPortfolio.result=null;redrawCrossPanel();}});

function comparison(){
 if(backend.ready)return heading('方案比较','比较已保存且通过当前核验的组合评估。',go('前往方案生成','generation'))+actualPortfolioComparison();
 const count=choose(state.front,5)*choose(state.back,2),cost=count*(state.additional?3:2),ready=state.calcResult&&state.calcResultKey===calcKey(),match=cost===state.budget;
 const summary=match?`当前前 ${state.front} 后 ${state.back} 复式${state.additional?'（追加）':''}为 ${count.toLocaleString()} 注、${cost.toLocaleString()} 元，与预算一致。`:`当前复式成本 ${cost.toLocaleString()} 元，预算 ${state.budget} 元；不同成本方案会单列，不作收益排名。`;
 return heading('方案比较','先把预算、组合结构和奖金情景说清楚，再比较结果。',button('登记为实验草稿','new-experiment'))+`${actualPortfolioComparison()}
 <div class="two-column"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>通用结构情景</h2><p>纸面成本 · 固定布局示例，不包含实际购买</p></div>${tag('历史奖金情景')}</div><div class="panel-body"><div class="form-row"><div class="field"><label for="budget">每期预算（元）</label><input id="budget" type="number" min="2" max="360" step="1" value="${state.budget}"><small>支持 2—360 元整数；各方案列明实际投入与余额。</small></div><div class="field"><label for="scenario">奖金情景</label><select id="scenario"><option>第 ${D.payoutScenario.issue} 期已公布奖金</option></select><small>事后情景，不代表下一期奖金。</small></div></div><div id="budget-note" class="notice ${match?'':'amber'}">${summary} ${state.calcBusy?'正在重新计算。':ready?'下方为当前参数的计算结果。':'参数尚未计算，点击下方“重新计算”。'}</div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>方案</th><th class="align-right">基本组合</th><th class="align-right">实际投入</th><th>与当前预算</th></tr></thead><tbody><tr><td>分散单式<small>固定种子，均匀随机，整注去重</small></td><td class="align-right">${Math.floor(state.budget/2)} 注</td><td class="align-right">${Math.floor(state.budget/2)*2} 元</td><td>${spendingLabel(Math.floor(state.budget/2)*2)}</td></tr><tr class="current-plan-row"><td>当前前 ${state.front} 后 ${state.back} 复式${state.additional?'（追加）':''}<small>${state.front} 选 5 × ${state.back} 选 2 / 与右侧同步</small></td><td class="align-right">${count.toLocaleString()} 注</td><td class="align-right">${cost.toLocaleString()} 元</td><td>${spendingLabel(cost)}</td></tr><tr><td>前区 4 胆 6 拖、后区 3 个<small>保留的固定结构参照</small></td><td class="align-right">18 注</td><td class="align-right">36 元</td><td>${spendingLabel(36)}</td></tr><tr><td>追加单式<small>每注 3 元</small></td><td class="align-right">${Math.floor(state.budget/3)} 注</td><td class="align-right">${Math.floor(state.budget/3)*3} 元</td><td>${spendingLabel(Math.floor(state.budget/3)*3)}</td></tr><tr><td>同号重复<small>同一组合重复计入成本，头奖覆盖仍为一组</small></td><td class="align-right">${Math.floor(state.budget/2)} 注</td><td class="align-right">${Math.floor(state.budget/2)*2} 元</td><td>${spendingLabel(Math.floor(state.budget/2)*2)}</td></tr><tr><td>不参与购买<small>资金不投入</small></td><td class="align-right">0 注</td><td class="align-right">0 元</td><td>${tag('净收益基准')}</td></tr></tbody></table></div></section>
 <section class="panel calculation-panel" id="calculation-panel"><div class="panel-head"><div><h2>中奖与整期盈利</h2><p>预算 ${state.budget} 元 / 第 ${D.payoutScenario.issue} 期奖金情景</p></div>${tag(state.calcBusy?'计算中':ready?'本次计算':'待计算',ready?'green':'blue')}<div class="calculation-toolbar"><div class="calculation-options"><label for="calc-samples">模拟次数</label><select id="calc-samples">${[[50000,'5 万次 / 快速'],[200000,'20 万次 / 默认'],[1000000,'100 万次 / 更小抽样误差']].map(([n,label])=>`<option value="${n}" ${state.samples===n?'selected':''}>${label}</option>`).join('')}</select></div><div class="actions">${state.calcBusy?button('停止计算','cancel-calculation'):button('重新计算','recalculate','primary','refresh')}</div></div></div><div id="comparison-results" aria-busy="${state.calcBusy}">${calculationResults()}</div></section></div>
 <aside class="stack"><section class="panel"><div class="panel-head"><h2>复式成本计算</h2>${tag('与比较表联动','green')}</div><div class="panel-body"><div class="form-row"><div class="field"><label for="front-count">前区选号数</label><select id="front-count">${[5,6,7,8,9,10,11,12].map(n=>`<option ${n===state.front?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="back-count">后区选号数</label><select id="back-count">${[2,3,4,5,6].map(n=>`<option ${n===state.back?'selected':''}>${n}</option>`).join('')}</select></div></div><label class="checkbox-row"><input id="calc-additional" type="checkbox" ${state.additional?'checked':''}><span>全部追加，每注 3 元</span></label><div class="calculator-result"><div><span>展开后 ${count.toLocaleString()} 注</span><strong class="num">${cost.toLocaleString()} <span>元</span></strong></div>${tag(cost>state.budget?'超出预算':'预算内',cost>state.budget?'amber':'green')}</div><p class="section-subtext">组合数 = C(${state.front},5) × C(${state.back},2)</p><div class="section-space"><button type="button" class="button" data-action="sync-budget" ${cost>360||cost<2?'disabled':''}>将 ${cost.toLocaleString()} 元同步为预算</button>${cost>360?'<p class="section-subtext">超过当前 360 元比较范围；成本仍可查看，请减少选号后同步。</p>':''}</div></div></section><section class="notice">重新计算不放大旧图表：复式、胆拖和重复投注使用精确组合概率，分散单式使用固定种子模拟。所有结果按各方案实际成本判断整期盈利。</section></aside></div>`;
}

const trainingModels=[
  ['random','随机基线','均匀随机 / 固定种子 / 去重','基线','无需训练'],
  ['statistical','统计策略','频率、逆频率与遗漏假设','统计','参数化策略'],
  ['tree','树模型','号码出现特征 / 时间窗口','ML','可配置'],
  ['lstm','LSTM','序列窗口 / 独立训练权重','序列','可配置'],
  ['transformer','Transformer','扩展模型接口，后续评估资源需求','扩展','后续范围']
];
const methodCopy={
  random:'均匀抽取合法号码，固定随机种子，并在同一组合包内去重。无需训练；作为相同预算下的对照，复式与胆拖还需匹配相同组合结构。',
  statistical:'在目标期之前的历史窗口内计算频率、逆频率或遗漏，再按预先固定的参数生成方案。历史特征仅作为待验证假设，需与同预算、同结构的随机方案比较。'
};
function training(){return heading('模型训练','固定数据、特征和参数；训练产物需再经独立回测验证。',button('方案生成','open-generation')+button('新建训练任务','train','primary','plus'))+`<section id="task-write-journal" class="panel section-space" aria-live="polite" hidden></section><section id="training-search-journal" class="panel section-space" aria-live="polite" hidden></section>
<div class="two-column training-layout"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>方法与模型</h2><p>选择方法，配置数据窗口与模型参数</p></div>${tag('4 类研究方法')}</div><div class="model-list">${trainingModels.map(([id,name,desc,symbol,status])=>{
  const copy=`<span class="model-symbol">${symbol}</span><div class="model-description"><h3>${name} ${tag(status,id==='transformer'?'':'blue')}</h3><p>${desc}</p></div>`;
  if(methodCopy[id])return `<details class="model-entry method-entry" name="method-explanations"><summary class="model-item">${copy}<span class="method-toggle"><span class="when-closed">查看方法</span><span class="when-open">收起说明</span>${icon('arrow')}</span></summary><div class="method-explanation"><p>${methodCopy[id]}</p><div class="section-space"><button type="button" class="button" data-action="open-generation" data-method="${id==='random'?'random':'hot'}">生成候选方案</button></div></div></details>`;
  return `<div class="model-entry"><div class="model-item">${copy}${id==='transformer'?'<button class="button" disabled>暂未开放</button>':`<button class="button" data-action="train" data-model="${name}" data-editor="${id}" aria-expanded="false" aria-controls="train-editor-${id}">配置训练</button>`}</div>${id==='transformer'?'':`<section class="inline-training-editor" id="train-editor-${id}" aria-labelledby="train-heading" hidden></section>`}</div>`;
}).join('')}</div></section><section class="panel"><div class="panel-head"><h2>训练任务</h2>${tag('任务记录')}</div><div id="training-job">${trainingJob()}</div></section></div><aside class="stack"><section class="panel"><div class="panel-head"><h2>训练前需要固定</h2></div><div class="panel-body"><ul class="check-list">${['数据快照与历史窗口','训练和验证分割','模型参数、种子与资源上限','独立保留集：尚未接入'].map((t,i)=>`<li>${icon(i===3?'clock':'check')}<span>${t}</span></li>`).join('')}</ul></div></section><section class="notice amber">模型评分未经校准时，不标为中奖概率。训练完成也不自动获得“方法有效”的结论。</section></aside></div>`;}
function trainingJob(){
  if(!backend.ready)return `<div class="panel-body"><div class="notice amber">本机训练服务未连接。请通过本机研究服务打开页面。</div></div>`;
  if(!backend.jobs.length)return `<div class="empty-state">${icon('model')}<h3>还没有训练任务</h3><p>${backend.snapshots.length?'已载入 '+backend.snapshots.length+' 份快照，可配置真实训练。':'请先载入本地历史快照，再配置训练。'}</p>${backend.snapshots.length?button('配置训练任务','train'):button('载入本地历史快照','import-snapshot')}</div>`;
  const labels={running:'运行中',complete:'已完成',failed:'失败',cancelled:'已取消'};
  return `<div class="panel-body">${backend.jobs.map(job=>`<div class="section-space"><div class="section-label"><div><h3>${escape(job.name)}</h3><p class="section-subtext">${job.request.config.method==='lstm'?'LSTM':'树模型'} · 数据截止 ${escape(job.request.config.cutoff)} · 窗口 ${job.request.config.window} 期${job.request.trial_group_id?` · 试验组 ${escape(job.request.trial_group_id)}`:''}${job.request.config.holdout_start&&job.request.config.holdout_end?` · 本次排除 ${escape(job.request.config.holdout_start)}—${escape(job.request.config.holdout_end)} 期`:' · 未声明排除范围'}${job.request.retry_of?` · 关联重试自 ${escape(job.request.retry_of)}`:''}</p></div>${tag(job.status==='complete'&&job.artifact_status==='review_required'?'产物待复核':labels[job.status]||job.status,job.status==='complete'&&job.artifact_status!=='review_required'?'green':job.status==='running'?'blue':'amber')}</div><p class="section-subtext">${job.status==='running'?'正在训练，完成后校验并保存模型产物。':job.status==='complete'?(job.artifact_status==='review_required'?'来源或产物需要复核，暂不可用于推理。':'产物摘要：'+escape(job.artifact_id)+'；尚需独立评估。'):job.status==='failed'?'失败原因：'+escape(job.error||'未知错误'):'任务已取消，未发布产物。'}</p>${trainingAttemptDetails(job)}<div class="actions">${job.status==='running'?`<button class="button danger" data-action="cancel-training" data-job="${escape(job.request_key)}">取消任务</button>`:job.status==='complete'&&job.artifact_status==='ready'?`<button class="button" data-action="use-trained-model" data-artifact="${escape(job.artifact_id)}">用此模型生成方案</button>`:['failed','cancelled'].includes(job.status)?`<button class="button" data-action="retry-training" data-job="${escape(job.request_key)}">按原配置关联重试</button>`:''}</div></div>`).join('')}</div>`;
}
function trainingAttemptDetails(job){
  const request=job?.request||{},config=request.config||{},snapshot=backend.snapshots.find(item=>item.id===config.snapshot_id);
  const issues=Array.isArray(snapshot?.issues)?snapshot.issues:[],first=issues.indexOf(request.first_issue),split=issues.indexOf(config.train_end),cutoff=issues.indexOf(config.cutoff);
  const trainStart=first>=0&&Number.isSafeInteger(config.window)?issues[first+config.window]:null;
  const trainEnd=split>=0?issues[split]:null,validationStart=split>=0&&split<cutoff?issues[split+1]:null,validationEnd=cutoff>=0?issues[cutoff]:null;
  const range=(start,end)=>start&&end?`${escape(start)}—${escape(end)}`:'无法从当前快照核对';
  return `<details class="section-space"><summary class="text-button">查看本次训练尝试与数据切分</summary><div class="section-space"><p class="section-subtext">请求键 ${escape(job.request_key)} · 试验组 ${escape(request.trial_group_id||'旧任务未分组')} · 快照 ${escape(config.snapshot_id||'缺失')} · 首期 ${escape(request.first_issue||'缺失')} · 训练目标 ${range(trainStart,trainEnd)} · 验证目标 ${range(validationStart,validationEnd)}（${split>=0&&cutoff>split?cutoff-split:'未知'} 期）。</p>${request.retry_of?`<p class="section-subtext">关联重试原任务 ${escape(request.retry_of)}；原任务状态 ${escape(({failed:'失败',cancelled:'已取消'})[backend.jobs.find(item=>item.request_key===request.retry_of)?.status]||'待核验')}，原失败记录仍保留。</p>`:''}<p class="section-subtext">算法 ${escape(config.algorithm_version||'缺失')} · 特征 ${escape(config.feature_schema_version||'缺失')} · 预处理 ${escape(config.preprocessing_version||'缺失')} · 窗口 ${escape(config.window??'缺失')} · 种子 ${escape(config.seed??'缺失')} · 参数 ${escape(JSON.stringify(config.parameters||{}))}。</p><div class="notice amber">此处展示的是训练任务内的验证切分；它参与模型开发，不是独立保留评估，也不能证明研究者未看过开奖数据。</div></div></details>`;
}

