function legacyOriginContent(records){if(!records.length)return '<p class="section-subtext">没有需要补充来源的旧自定义评估。</p>';return records.map(item=>{if(item.status!=='available')return `<div class="notice amber">旧评估 ${escape(item.evaluation_key.slice(0,24))} 无法核验，暂不能补录。</div>`;const input=item.custom_input,history=item.declarations.map(d=>`<li>${escape(d.kind==='synthetic'?'本人声明人工设定':'本人声明参考第 '+d.issue+' 期')} · ${escape(d.reason)} · ${escape(d.created_at)}</li>`).join('');return `<details class="section-space"><summary class="text-button">${escape(input.label)} · 评估 ${escape(item.evaluation_key.slice(0,24))}${history?' · 已有声明':' · 未声明'}</summary><p class="section-subtext">原始奖金（元）：${Object.entries(input.payouts).map(([key,value])=>escape(key)+'：'+escape(value)).join(' / ')}</p>${history?`<p class="section-subtext">既有声明：</p><ul>${history}</ul>`:'<p class="section-subtext">该记录尚未声明来源，当前不能判定是否涉及保留范围。</p>'}<form class="legacy-origin-form section-space" data-evaluation="${escape(item.evaluation_key)}"><div class="form-row"><div class="field"><label>来源声明<select name="kind" required><option value="">请选择</option><option value="synthetic">人工设定的假设值</option><option value="historical">参考某历史奖期</option></select></label></div><div class="field"><label>参考期号<input name="issue" inputmode="numeric" pattern="[0-9]{5}" disabled></label></div></div><div class="field"><label>本人说明<input name="reason" maxlength="1000" required></label></div><label class="checkbox-row"><input type="checkbox" name="confirm" required><span>我确认按记忆如实声明；系统无法验证本人是否已见过数据，既有声明不会删除。</span></label><div class="error-text" role="status"></div><button type="submit" class="button">追加来源声明</button></form></details>`;}).join('');}
async function refreshLegacyOrigins(force=false){if(legacyOriginTask){const prior=await legacyOriginTask;if(!force)return prior;return refreshLegacyOrigins();}const task=loadLegacyOrigins();legacyOriginTask=task;try{return await task;}finally{if(legacyOriginTask===task)legacyOriginTask=null;}}
async function loadLegacyOrigins(){const root=el('legacy-origin-list');if(!root)return true;const epoch=++legacyOriginEpoch,connection=connectionEpoch;try{const response=await fetch('/api/custom-origin-declarations',{credentials:'same-origin'});if(!response.ok)throw Error('读取失败');const data=await response.json();if(!root.isConnected||state.page!=='backtest'||epoch!==legacyOriginEpoch||connection!==connectionEpoch)return false;const drafts=[...root.querySelectorAll('.legacy-origin-form')].filter(form=>form.dataset.dirty==='true').map(form=>({form,open:!!form.closest('details')?.open}));root.innerHTML=legacyOriginContent(data.records||[]);for(const draft of drafts){const replacement=[...root.querySelectorAll('.legacy-origin-form')].find(form=>form.dataset.evaluation===draft.form.dataset.evaluation);if(replacement){const details=replacement.closest('details');replacement.replaceWith(draft.form);if(details&&draft.open)details.open=true;if(draft.form.dataset.originUnavailable==='true'){delete draft.form.dataset.originUnavailable;const submit=draft.form.querySelector('[type=submit]');if(submit)submit.disabled=draft.form.dataset.submitting==='true';}}else{root.insertAdjacentHTML('beforeend','<div class="notice amber">一份正在编辑的旧记录已无法核验，内容保留但不能提交。</div>');draft.form.dataset.originUnavailable='true';const submit=draft.form.querySelector('[type=submit]');if(submit)submit.disabled=true;root.append(draft.form);}}return true;}catch(e){if(root.isConnected&&state.page==='backtest'&&epoch===legacyOriginEpoch&&connection===connectionEpoch&&!root.querySelector('.legacy-origin-form[data-dirty="true"]'))root.textContent='旧来源声明读取失败，请重新打开页面。';return false;}}
async function submitLegacyOrigin(form){const f=new FormData(form),kind=String(f.get('kind')||''),button=form.querySelector('[type=submit]'),status=form.querySelector('[role=status]'),initial=JSON.stringify([kind,f.get('issue'),f.get('reason'),f.get('confirm')]);if(form.dataset.originUnavailable==='true'){status.textContent='旧记录暂不可核验，请恢复后再提交。';return;}form.dataset.submitting='true';button.disabled=true;try{const entry=await getDeclarationWriteJournal().begin({evaluation_key:form.dataset.evaluation,kind,issue:kind==='historical'?String(f.get('issue')||''):null,reason:String(f.get('reason')||''),confirmed:f.get('confirm')==='on'});const current=new FormData(form);if(entry.phase==='accepted'&&JSON.stringify([current.get('kind'),current.get('issue'),current.get('reason'),current.get('confirm')])===initial){delete form.dataset.dirty;const audit=el('holdout-audit-result');if(audit)audit.innerHTML='<div class="notice">声明已保存；请重新核对范围后再固定。</div>';await Promise.all([refreshLegacyOrigins(true),refreshReservations(true)]);}else if(form.isConnected)status.textContent=entry.phase==='fenced'?'原请求已封止，可在上方选择关联重试。':'声明结果待确认，请在上方查询原请求。';await refreshDeclarationWriteJournal();}catch(e){if(form.isConnected)status.textContent=e.message;await refreshDeclarationWriteJournal();}finally{delete form.dataset.submitting;if(button.isConnected)button.disabled=form.dataset.originUnavailable==='true';}}
document.addEventListener('change',event=>{const form=event.target.closest('.legacy-origin-form');if(!form||event.target.name!=='kind')return;form.dataset.dirty='true';const input=form.querySelector('[name=issue]'),historical=event.target.value==='historical';input.disabled=!historical;input.required=historical;});
