const sourceFileChecks=new WeakMap();
function sourceDocumentLink(review){const sha=typeof review.document_sha256==='string'&&/^[0-9a-f]{64}$/.test(review.document_sha256)?review.document_sha256:null,id=typeof review.review_id==='string'&&/^[0-9a-f]{64}$/.test(review.review_id)?review.review_id:null;return `<div class="section-space" data-source-panel data-source-id="${escape(id||'')}"><p class="section-subtext">原文已留存在本机，摘要 ${escape(sha||'待核验')}。原样下载暂不可用；支持文本、PDF、PNG 和 JPEG 的本机预览。</p>${sha?`<label class="text-button">选择本人保存的原文件核对摘要<input type="file" data-source-sha="${escape(sha)}"></label><p class="section-subtext" data-source-check role="status" aria-live="polite">文件只在浏览器内计算摘要，不上传。</p>`:''}${id?`<button type="button" class="button" data-source-preview-load data-offset="0">查看留存资料</button><div data-source-viewer hidden><p class="section-subtext" data-source-preview-status role="status" aria-live="polite"></p><pre class="draw-raw source-preview-text" data-source-preview-text hidden></pre><img class="source-preview-image" data-source-preview-image alt="来源资料图像预览" hidden><div class="actions"><button type="button" class="button" data-source-preview-prev data-source-preview-load disabled>上一段</button><button type="button" class="button" data-source-preview-next data-source-preview-load disabled>下一段</button></div></div>`:''}</div>`;}
