async function captureReviewSource(button){
  const form=button.closest('#review-form'),status=form?.querySelector('#review-capture-status'),input=form?.querySelector('#review-file');
  if(!form||!status||!input)return;
  if(form.dataset.saving==='true'||form.dataset.capturing==='true')return;
  const values=new FormData(form),kind=String(values.get('kind')||''),sourceUrl=String(values.get('url')||'').trim();
  if(!sourceUrl){status.textContent='请先填写允许的官方 HTTPS 来源网址。';return;}
  const signature=kind+'\n'+sourceUrl,sequence=String(Number(form.dataset.captureSequence||0)+1);
  const submit=form.querySelector('button[type="submit"]');form.dataset.captureSequence=sequence;form.dataset.capturing='true';
  button.disabled=true;if(submit)submit.disabled=true;status.textContent='正在通过本机服务获取官方来源字节…';
  try{
    const {response,json}=await fetchCheckedConnection('/api/source-review-capture',{
      method:'POST',credentials:'same-origin',
      headers:{'Content-Type':'application/json','X-DLT-CSRF':backend.csrf},
      body:JSON.stringify({kind,source_url:sourceUrl})
    },'官方资料获取失败');
    const data=await json();
    if(!response.ok)throw new Error(data.error||'官方资料获取失败');
    if(!form.isConnected||form.dataset.captureSequence!==sequence)return;
    const current=new FormData(form);
    if(String(current.get('kind'))+'\n'+String(current.get('url')||'').trim()!==signature){
      status.textContent='资料类型或网址已变化，没有替换文件；请按当前网址重新获取。';return;
    }
    if(data.source_url!==sourceUrl||!Number.isSafeInteger(data.document_size)||data.document_size<1||data.document_size>5*1024*1024
      ||typeof data.document_base64!=='string'||data.document_base64.length>7*1024*1024||!/^[0-9a-f]{64}$/.test(data.document_sha256||''))
      throw new Error('来源抓取结果字段无效');
    const bytes=Uint8Array.from(atob(data.document_base64),char=>char.charCodeAt(0));
    if(bytes.length!==data.document_size)throw new Error('来源抓取文件长度不符');
    const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),value=>value.toString(16).padStart(2,'0')).join('');
    if(hash!==data.document_sha256)throw new Error('来源抓取文件摘要不符');
    let fileName='official-source.bin';
    try{const leaf=new URL(sourceUrl).pathname.split('/').pop();if(leaf&&leaf!=='.'&&leaf!=='..'&&/^[A-Za-z0-9._-]{1,120}$/.test(leaf))fileName=leaf;}catch{}
    const file=new File([bytes],fileName,{type:data.content_type||'application/octet-stream'});
    if(typeof DataTransfer==='function'){
      const transfer=new DataTransfer();transfer.items.add(file);input.files=transfer.files;
      form.dataset.captureApplying='true';input.dispatchEvent(new Event('change',{bubbles:true}));delete form.dataset.captureApplying;
      form.dataset.capturedUrl=sourceUrl;form.dataset.capturedKind=kind;form.dataset.capturedSha=hash;
      status.textContent=`已获取 ${file.size} 字节（SHA-256 ${hash}）。文件已放入表单；请人工核对原件和结构化内容。抓取与摘要不能证明发布者、适用期或发布时间。`;
    }else{
      const objectUrl=URL.createObjectURL(file),link=document.createElement('a');link.href=objectUrl;link.download=fileName;
      document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(objectUrl),30000);
      status.textContent=`已下载 ${file.size} 字节（SHA-256 ${hash}）。请手动选择下载文件并核对；抓取与摘要不能证明发布者、适用期或发布时间。`;
    }
  }catch(error){
    delete form.dataset.captureApplying;
    if(form.isConnected&&form.dataset.captureSequence===sequence)status.textContent='获取失败：'+error.message;
  }finally{delete form.dataset.capturing;if(button.isConnected)button.disabled=false;if(submit?.isConnected)submit.disabled=false;}
}
