async function submitSourceCorrection(form){const f=new FormData(form),signature=formValueSignature(form),old=backend.reviews.find(r=>r.review_id===f.get('old')),next=backend.reviews.find(r=>r.review_id===f.get('new')),submit=form.querySelector('button[type="submit"]');if(!old||!next||old.review_id===next.review_id||old.kind!==next.kind){form.querySelector('#correction-error').textContent='请选择不同且类型相同的资料。';return;}const note=String(f.get('note')).trim(),body={old_review_id:old.review_id,new_review_id:next.review_id,note,confirmed:f.get('confirmed')==='on'};if(f.get('scope')==='issue'){if(old.kind==='calendar'){form.querySelector('#correction-error').textContent='日历资料已限定同一期，请选择所有引用该资料的奖期。';return;}body.issue=String(f.get('issue')||'').trim();if(!/^[0-9]{5}$/.test(body.issue)){form.querySelector('#correction-error').textContent='请输入五位指定奖期。';return;}}const request={old_review_id:old.review_id,new_review_id:next.review_id,issue:body.issue??null,note,confirmed:true};submit.disabled=true;try{const result=await getSourceWriteJournal().begin('source_correction',request,body);if(result.phase!=='accepted')throw new Error('更正请求已暂存，服务端结果未知；请查询原请求。');await refreshBackend();await refreshSourceWriteJournal();if(!form.isConnected)return;if(formValueSignature(form)===signature){delete form.dataset.dirty;form.closest('details').open=false;toast('更正已受理，后续结算重算状态请查看各实验记录。');}else{form.dataset.dirty='true';form.querySelector('#correction-error').textContent='原提交的更正已受理；提交期间修改的表单内容已保留，但未提交。';form.closest('details').open=true;}}catch(e){if(form.isConnected)form.querySelector('#correction-error').textContent=reviewError(e.message);else toast('更正请求结果待确认：'+reviewError(e.message));await refreshSourceWriteJournal();}finally{if(submit.isConnected)submit.disabled=false;}}
