function trainingSearchValues(raw,fallback,{integer,min,max,label}){
  const source=String(raw||'').trim(),parts=source?source.split(',').map(item=>item.trim()):[String(fallback)];
  if(parts.some(item=>!item)||parts.length>8)throw new Error(`${label}候选须为 1 至 8 个逗号分隔数值。`);
  const values=[];
  for(const part of parts){
    if(!(integer?/^(?:0|[1-9][0-9]*)$/:/^(?:0|[1-9][0-9]*)(?:\.[0-9]+)?$/).test(part))throw new Error(`${label}候选格式无效：${part}`);
    const value=Number(part);if(!Number.isFinite(value)||value<min||value>max)throw new Error(`${label}候选超出 ${min} 至 ${max} 的限额。`);
    if(!values.includes(value))values.push(value);
  }
  return values;
}
function trainingSearchRequests(form,baseRequest){
  const f=new FormData(form),method=baseRequest.config.method,limits=backend.trainingLimits;
  const entries=method==='tree'?[['max_depth','search_max_depth',limits.tree_max_depth,true,'树最大深度'],['min_leaf','search_min_leaf',limits.tree_min_leaf,true,'叶节点最少样本']]:[['hidden_size','search_hidden_size',limits.lstm_hidden_size,true,'隐藏层维度'],['epochs','search_epochs',limits.lstm_epochs,true,'训练轮数'],['learning_rate','search_learning_rate',limits.lstm_learning_rate,false,'学习率']];
  const dimensions=entries.map(([key,field,bounds,integer,label])=>trainingSearchValues(f.get(field),baseRequest.config.parameters[key],{integer,min:bounds[0],max:bounds[1],label}));
  const count=dimensions.reduce((total,values)=>total*values.length,1);if(count>64)throw new Error(`参数笛卡尔积为 ${count} 个尝试，超过每组 64 个的上限。`);
  const requests=[];
  function expand(index,parameters){if(index===entries.length){requests.push({...baseRequest,config:{...baseRequest.config,parameters:{...parameters}}});return;}
    const key=entries[index][0];for(const value of dimensions[index])expand(index+1,{...parameters,[key]:value});}
  expand(0,{});return requests;
}
